provider_settings_save($id,6,'Cloud context changed',true,'',$password);$cloudHtml=$renderWorkspace('cloud');

$before=[$dns,$reads,$writes,prtn_snapshot()];
prtn_deny('Save refuses revoked owner before consuming approval',fn()=>cwp_test_owner_revoked(fn()=>prtn_change($review)));
