foreach(['confirmation','proof','text'] as $bad){$before=[$dns,$reads,$writes,prtn_snapshot()];prtn_deny('Save refuses altered '.$bad,fn()=>provider_password_reset_template_change($review['request_id'],$profile,1,$review['observation_id'],$bad==='proof'?str_repeat('0',64):$review['review_sha256'],$bad==='text'?$desired.' changed':$desired,$bad!=='confirmation',$password,'prtn_dns','prtn_perform'));prtn_ok('Invalid '.$bad.' consumes no approval or provider call',[$dns,$reads,$writes,prtn_snapshot()]===$before);}

